<?php
declare(strict_types=1);

namespace FireDine;

use DomainException;
use PDO;

final class Application
{
    public function __construct(
        private PDO $db,
        private ProductRepository $products,
        private PricingService $pricing,
        private QuoteService $quotes,
        private EnquiryService $enquiries,
        private CaptchaService $captcha,
        private string $root
    ) {}

    public function run(): void
    {
        $path=rtrim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/','/')?:'/';
        $method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');
        try {
            if(str_starts_with($path,'/api/')){$this->api($path,$method);return;}
            if($path==='/admin'||str_starts_with($path,'/admin/')){$this->admin($path,$method);return;}
            if(preg_match('#^/brochure/(\d+)$#',$path,$m)){$this->downloadBrochure((int)$m[1]);return;}
            if(preg_match('#^/product/([a-z0-9-]+)$#',$path,$m)){header('Location: /product?slug='.rawurlencode($m[1]),true,302);return;}
            if(preg_match('#^/category/([a-z0-9-]+)/([a-z0-9-]+)$#',$path,$m)){$this->categoryRoute($m[1],$m[2]);return;}
            if(preg_match('#^/category/([a-z0-9-]+)$#',$path,$m)){$this->categoryRoute($m[1]);return;}
            match($path){
                '/'=>$this->frontendPage('home'),'/shop'=>$this->frontendPage('shop'),'/category'=>$this->shop(),'/product'=>$this->frontendPage('product'),
                '/cart','/checkout'=>$this->checkout(),'/about'=>$this->frontendPage('about'),'/installation'=>$this->frontendPage('installation'),'/gallery'=>$this->frontendPage('gallery'),
                '/contact'=>$this->contact(),'/faq','/faqs'=>$this->frontendPage('faqs'),'/privacy-policy'=>$this->frontendPage('privacy-policy'),'/terms','/terms-of-service'=>$this->frontendPage('terms'),
                '/accessories'=>$this->frontendPage('accessories'),'/advice'=>$this->frontendPage('advice'),'/commercial-ovens'=>$this->frontendPage('commercial-ovens'),
                '/compare'=>$this->frontendPage('compare'),'/diy-ovens'=>$this->frontendPage('diy-ovens'),'/fireplaces'=>$this->frontendPage('fireplaces'),
                '/mobile-compact-ovens'=>$this->frontendPage('mobile-compact-ovens'),'/outdoor-models'=>$this->frontendPage('outdoor-models'),
                '/pizza-ovens'=>$this->frontendPage('pizza-ovens'),'/residential-pizza-ovens'=>$this->frontendPage('residential-pizza-ovens'),
                '/stoneskin'=>$this->frontendPage('stoneskin'),
                '/sitemap.xml'=>$this->sitemap(),'/robots.txt'=>$this->robots(),default=>$this->notFound(),
            };
        } catch(RateLimitException $e){header('Retry-After: '.$e->retryAfter);$this->respondError($path,$e->getMessage(),429,$e);}
        catch(NotFoundException $e){$this->respondError($path,$e->getMessage(),404,$e);}
        catch(DomainException $e){$this->respondError($path,$e->getMessage(),422,$e);}
        catch(\Throwable $e){$this->respondError($path,'The request could not be completed.',500,$e);}
    }

    private function respondError(string $path,string $message,int $status,\Throwable $exception): void
    {
        error_log($exception->__toString());
        if(str_starts_with($path,'/api/'))$this->json(['error'=>['message'=>$message,'status'=>$status]],$status);
        $this->layout($status===404?'Page not found':'Request not completed','<section class="fd-page"><h1>'.($status===404?'Page not found':'We could not complete that request').'</h1><p>'.self::e($message).'</p><p><a class="fd-btn" href="'.self::e($_SERVER['HTTP_REFERER']??'/').'">Go back</a></p></section>',$status);
    }

    private function api(string $path,string $method): void
    {
        if(str_ends_with($path,'.php'))$path=substr($path,0,-4);
        $known=['/api/health','/api/categories','/api/products','/api/product','/api/configuration-price','/api/quotes','/api/enquiries','/api/brochure','/api/brochure.php','/api/recaptcha-public','/api/tracking-config','/api/tracking-event'];
        if($path==='/api/health'&&$method==='GET'){$meta=[];$stmt=$this->db->query("SELECT meta_key,meta_value FROM app_meta WHERE meta_key LIKE 'fire_dine_%'");foreach($stmt->fetchAll() as $row)$meta[$row['meta_key']]=$row['meta_value'];$this->json(['status'=>'ok','database'=>true,'version'=>$meta['fire_dine_application_version']??'unknown','migration'=>$meta['fire_dine_database_migration_version']??'unknown']);}
        if($path==='/api/categories'&&$method==='GET')$this->json(['categories'=>$this->products->categories()]);
        if($path==='/api/products'&&$method==='GET'){
            $slug=trim((string)($_GET['slug']??''));
            if($slug!==''){$product=$this->products->findBySlug($slug);$product?$this->json(['product'=>$product]):$this->json(['error'=>['message'=>'Product not found.','status'=>404]],404);}
            $filters=$_GET;$filters['per_page']=isset($_GET['limit'])?(int)$_GET['limit']:48;$this->json($this->products->search($filters));
        }
        if($path==='/api/product'&&$method==='GET'){$product=$this->products->findBySlug((string)($_GET['slug']??''));$product?$this->json(['product'=>$product]):$this->json(['error'=>['message'=>'Product not found.','status'=>404]],404);}
        if($path==='/api/quotes'&&$method==='GET')$this->json(['csrf_token'=>$this->csrf(),'idempotency_key'=>bin2hex(random_bytes(24)),'captcha_site_key'=>$this->captcha->siteKey()],200,['Cache-Control'=>'no-store']);
        if($path==='/api/configuration-price'&&$method==='POST'){$input=$this->input();$this->checkApiCsrf($input);$this->enforcePublicRateLimit('configuration-price',120,60);$this->json($this->pricing->price($input));}
        if($path==='/api/quotes'&&$method==='POST'){$input=$this->input();$this->checkApiCsrf($input);$this->captcha->verify((string)($input['captcha_token']??''),$_SERVER['REMOTE_ADDR']??'');$this->enforcePublicRateLimit('quote-submit',10,3600);$this->json($this->quotes->submit($input),201);}
        if($path==='/api/enquiries'&&$method==='POST'){$this->submitEnquiry($this->input());}
        if($path==='/api/recaptcha-public'&&$method==='GET')$this->json(['enabled'=>$this->captcha->siteKey()!==null,'site_key'=>$this->captcha->siteKey()]);
        if($path==='/api/tracking-config'&&$method==='GET')$this->json(['ga4_measurement_id'=>getenv('GA4_MEASUREMENT_ID')?:null,'meta_pixel_id'=>getenv('META_PIXEL_ID')?:null]);
        if($path==='/api/tracking-event'&&$method==='POST'){$this->recordTrackingEvent($this->input());}
        if($path==='/api/brochure.php'&&$method==='GET')$this->redirectLegacyBrochure();
        if($path==='/api/brochure'&&$method==='GET'){$this->downloadBrochure((int)($_GET['id']??0));return;}
        if(in_array($path,$known,true)){$this->json(['error'=>['message'=>'Method not allowed.','status'=>405]],405,['Allow'=>$this->allowedMethods($path)]);}
        $this->json(['error'=>['message'=>'Endpoint not found.','status'=>404]],404);
    }

    private function submitEnquiry(array $input): never
    {
        $this->checkApiCsrf($input);
        $this->captcha->verify((string)($input['captcha_token']??''),$_SERVER['REMOTE_ADDR']??'');
        $this->enforcePublicRateLimit('enquiry-submit',8,3600);
        $this->json($this->enquiries->submit($input),201);
    }

    private function recordTrackingEvent(array $input): never
    {
        $this->enforcePublicRateLimit('tracking-event',240,60);$event=trim((string)($input['event_name']??''));if(!preg_match('/^[a-zA-Z0-9_.-]{1,80}$/',$event))throw new DomainException('Invalid tracking event.');$payload=json_encode(array_intersect_key($input,['event_name'=>true,'page'=>true,'source'=>true]),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$stmt=$this->db->prepare("INSERT INTO tracking_events(event_id,event_name,page_url,payload_json,source) VALUES(:id,:name,:page,:payload,'browser')");try{$stmt->execute(['id'=>bin2hex(random_bytes(16)),'name'=>$event,'page'=>substr((string)($input['page']??''),0,2000),'payload'=>$payload]);}catch(\Throwable $e){error_log($e->__toString());}$this->json(['accepted'=>true],202);
    }

    private function home(): void
    {
        $featured=$this->products->list(['featured'=>true,'per_page'=>6]);if(!$featured)$featured=array_slice($this->products->list(['per_page'=>6]),0,6);
        $body='<section class="fd-hero fd-home-hero"><div><p class="eyebrow">Handcrafted in Vanderbijlpark</p><h1>Gather around real fire</h1><p>South African-made wood-fired pizza ovens, practical accessories and selected closed-combustion fireplaces.</p><div class="fd-actions"><a class="fd-btn" href="/category/pizza-ovens">Explore pizza ovens</a><a class="fd-btn fd-btn-secondary" href="/contact">Speak to Fire &amp; Dine</a></div></div></section>'
            .'<section class="fd-page"><p class="eyebrow">Choose your range</p><h2>Built for the way you cook</h2><div class="fd-category-grid"><a href="/category/pizza-ovens"><img src="/assets/images/optimized/category-pizza-960.webp" alt="Fire & Dine pizza ovens"><h3>Pizza Ovens</h3></a><a href="/category/accessories"><img src="/assets/images/optimized/category-accessories-960.webp" alt="Pizza oven accessories"><h3>Accessories</h3></a><a href="/category/fireplace"><img src="/assets/images/optimized/category-fireplace-960.webp" alt="Closed combustion fireplaces"><h3>Fireplace</h3></a></div></section>'
            .'<section class="fd-page"><p class="eyebrow">The collection</p><h2>Featured products</h2><div class="fd-grid">'.$this->cards($featured).'</div></section>'
            .'<section class="fd-split fd-page"><img loading="lazy" src="/assets/images/optimized/about-fire-cooking-1200.webp" alt="Cooking together around a wood-fired oven"><div><p class="eyebrow">Fire, food and people</p><h2>Made for memorable cooking</h2><p>From compact domestic ovens to mobile and commercial ranges, Fire &amp; Dine helps customers choose the right oven, finish and accessories for the installation.</p><a class="fd-btn" href="/about">Our story</a></div></section>';
        $this->layout('Wood-fired ovens, accessories and fireplaces',$body,200,'South African-made Fire & Dine wood-fired pizza ovens, accessories and selected fireplaces.','/');
    }

    private function frontendPage(string $view): void
    {
        $file=$this->root.'/resources/views/pages/'.basename($view).'.php';
        if(!is_file($file)){$this->notFound();return;}
        header('Content-Type: text/html; charset=utf-8');
        require $file;
    }

    private function shop(string $category='',string $subcategory=''): void
    {
        $filters=['q'=>$_GET['q']??'','category'=>$category?:($_GET['category']??''),'subcategory'=>$subcategory?:($_GET['subcategory']??''),'page'=>$_GET['page']??1,'per_page'=>24];$result=$this->products->search($filters);$products=$result['products'];$cats=$this->products->categories();$nav='';$currentName='All products';
        foreach($cats as $cat){if($filters['category']===$cat['slug'])$currentName=$cat['name'];$nav.='<div class="fd-filter-group"><a'.($filters['category']===$cat['slug']?' aria-current="page"':'').' href="/category/'.self::e($cat['slug']).'">'.self::e($cat['name']).'</a>';foreach($cat['children'] as $child){if($filters['subcategory']===$child['slug'])$currentName=$child['name'];$nav.='<a class="fd-subfilter"'.($filters['subcategory']===$child['slug']?' aria-current="page"':'').' href="/category/'.self::e($cat['slug']).'/'.self::e($child['slug']).'">'.self::e($child['name']).'</a>';}$nav.='</div>';}
        $canonical=$filters['subcategory']?'/category/'.$filters['category'].'/'.$filters['subcategory']:($filters['category']?'/category/'.$filters['category']:'/shop');$description='Browse '.strtolower($currentName).' from Fire & Dine, with current product availability and quotation options.';
        $body='<section class="fd-page"><nav class="fd-breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span>›</span><span>'.self::e($currentName).'</span></nav><p class="eyebrow">Fire &amp; Dine catalogue</p><h1>'.self::e($currentName).'</h1><p>'.self::e($description).'</p><form class="fd-search" action="'.$canonical.'" method="get"><label for="shop-search">Search products</label><div><input id="shop-search" name="q" value="'.self::e((string)$filters['q']).'" maxlength="100" placeholder="Search by name or SKU"><button class="fd-btn">Search</button><a href="'.$canonical.'">Reset</a></div></form><div class="fd-shop"><aside aria-label="Product categories"><h2>Categories</h2><a href="/shop">All products</a>'.$nav.'</aside><div><p class="fd-count">'.$result['pagination']['total'].' product'.($result['pagination']['total']===1?'':'s').'</p><div class="fd-grid">'.$this->cards($products).'</div>'.$this->pagination($result['pagination'],$canonical).'</div></div></section>';
        $this->layout($currentName,$body,200,$description,$canonical);
    }

    private function categoryRoute(string $category,string $subcategory=''): void
    {
        $oldPath=$subcategory!==''?$category.'/'.$subcategory:$category;
        $stmt=$this->db->prepare("SELECT new_path,redirect_code FROM category_slug_redirects WHERE old_path=? AND is_active=1 LIMIT 1");$stmt->execute([$oldPath]);$redirect=$stmt->fetch();
        if($redirect){header('Location: /category/'.implode('/',array_map('rawurlencode',explode('/',(string)$redirect['new_path']))),true,(int)$redirect['redirect_code']);return;}
        if($subcategory!==''){$stmt=$this->db->prepare("SELECT child.id FROM categories child JOIN categories parent ON parent.id=child.parent_id WHERE parent.slug=? AND child.slug=? AND parent.is_active=1 AND child.is_active=1 LIMIT 1");$stmt->execute([$category,$subcategory]);if($stmt->fetchColumn()===false){$this->notFound();return;}}
        else{$stmt=$this->db->prepare("SELECT c.parent_id,p.slug parent_slug FROM categories c LEFT JOIN categories p ON p.id=c.parent_id WHERE c.slug=? AND c.is_active=1 LIMIT 1");$stmt->execute([$category]);$row=$stmt->fetch();if(!$row){$this->notFound();return;}if($row['parent_id']!==null){header('Location: /category/'.rawurlencode((string)$row['parent_slug']).'/'.rawurlencode($category),true,301);return;}}
        $this->shop($category,$subcategory);
    }

