        foreach($product['options'] as $group){if($group['type']==='display')continue;$selectors.='<fieldset data-option-group data-option-code="'.self::e($group['code']).'" data-option-type="'.self::e($group['type']).'" data-base-required="'.($group['required']?'true':'false').'" data-required-when="'.self::e(json_encode($group['metadata']['required_when']??null,JSON_UNESCAPED_SLASHES)).'"><legend>'.self::e($group['label']).($group['required']?' *':'').'</legend>';foreach($group['values'] as $value){$suffix=$value['pricing_mode']==='request_quote'?' — Request a quote':(((float)($value['price_adjustment']??0))>0?' — +'.self::money($value['price_adjustment']):' — Included');$selectors.='<label class="fd-choice"><input type="'.($group['type']==='multiple'?'checkbox':'radio').'" name="option_value_ids[]" value="'.(int)$value['id'].'" data-option-value data-value-code="'.self::e($value['code']).'" data-condition="'.self::e(json_encode($value['conditions']??null,JSON_UNESCAPED_SLASHES)).'"> '.self::e($value['label'].$suffix).'</label>';}$selectors.='</fieldset>';}
        $gallery=$product['gallery']?:[['url'=>$product['image_url'],'alt'=>$product['name'],'primary'=>true]];$primary=$product['image_url'];$thumbs='';foreach($gallery as $image){if($image['primary'])$primary=$image['url'];$thumbs.='<button type="button" class="fd-gallery-thumb" data-gallery-image="'.self::e($image['url']).'" aria-label="Show '.self::e($image['alt']).'"><img loading="lazy" src="'.self::e($image['url']).'" alt=""></button>';}
        $prices=array_map(fn($v)=>(float)($v['sale_price']??$v['regular_price']),$availableVariations);$base=$product['sale_price']??$product['regular_price'];$priceText=$prices?(min($prices)===max($prices)?self::money(min($prices)):self::money(min($prices)).'–'.self::money(max($prices))):($base===null?'Request a quote':self::money($base));$outOfStock=$product['stock_status']==='out_of_stock'||($product['product_type']==='variable'&&!$availableVariations);
        $specs=$this->renderSpecifications($product['specifications_data']??[]);$related=$product['related']?'<section class="fd-related"><h2>Complete your setup</h2><div class="fd-grid">'.$this->cards($product['related']).'</div></section>':'';
        $form=$outOfStock?'<p class="fd-stock-out" role="status">Currently out of stock. Contact Fire &amp; Dine for availability.</p>':'<form class="fd-config" data-product-form><input type="hidden" name="product_id" value="'.(int)$product['id'].'">'.$selectors.'<label>Quantity<input type="number" name="quantity" min="1" max="99" value="1" required></label><p class="fd-live-price" aria-live="polite">'.$priceText.'</p><button class="fd-btn" type="submit">Add to quote</button><p class="fd-form-status" role="status" tabindex="-1"></p></form>';
