        foreach($rows as $row){$caption='<figcaption><strong>'.self::e($row['title']).'</strong>'.($row['description']?'<span>'.self::e($row['description']).'</span>':'').'</figcaption>';if($row['media_type']==='video'&&$row['file_path']){$source='/'.ltrim($row['file_path'],'/');$poster=$row['thumbnail_path']?'/'.ltrim($row['thumbnail_path'],'/'):'';$items.='<figure class="fd-gallery-item"><video controls preload="metadata"'.($poster?' poster="'.self::e($poster).'"':'').' aria-label="'.self::e($row['alt_text']?:$row['title']).'"><source src="'.self::e($source).'" type="'.self::e($row['mime_type']?:'video/mp4').'">Your browser does not support this video.</video>'.$caption.'</figure>';continue;}$external=self::safeExternalUrl((string)($row['external_url']??''));if($row['media_type']==='video'&&$external!==''){$thumb=$row['thumbnail_path']?'/'.ltrim($row['thumbnail_path'],'/'):'/assets/images/hero-selected/gallery-fire-dining-960.webp';$items.='<figure class="fd-gallery-item"><a href="'.self::e($external).'" rel="noopener"><img loading="lazy" src="'.self::e($thumb).'" alt="'.self::e($row['alt_text']?:$row['title']).'"></a>'.$caption.'</figure>';continue;}if(!$row['file_path'])continue;$items.='<figure class="fd-gallery-item"><img loading="lazy" src="'.self::e('/'.ltrim($row['file_path'],'/')).'" alt="'.self::e($row['alt_text']?:$row['title']).'">'.$caption.'</figure>';}
