    private function downloadBrochure(int $id): void
    {
        if($id<1){$this->notFound();return;}$stmt=$this->db->prepare("SELECT id,title,file_path,stored_filename,original_filename,mime_type FROM brochures WHERE id=? AND enabled=1 LIMIT 1");$stmt->execute([$id]);$brochure=$stmt->fetch();if(!$brochure){$this->notFound();return;}$relative=ltrim((string)($brochure['file_path']?:'uploads/brochures/'.$brochure['stored_filename']),'/');$base=realpath($this->root.'/public/uploads/brochures');$file=realpath($this->root.'/public/'.$relative);if(!$base||!$file||!str_starts_with($file,$base.DIRECTORY_SEPARATOR)||!is_file($file)||strtolower(pathinfo($file,PATHINFO_EXTENSION))!=='pdf'){$this->notFound();return;}$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($file);if($mime!=='application/pdf'){$this->notFound();return;}$this->db->beginTransaction();try{$this->db->prepare("UPDATE brochures SET download_count=download_count+1 WHERE id=?")->execute([$id]);$this->db->prepare("INSERT INTO brochure_downloads(brochure_id,ip_hash,user_agent_hash) VALUES(?,?,?)")->execute([$id,hash('sha256',($_SERVER['REMOTE_ADDR']??'').'|'.(getenv('APP_KEY')?:'local')),hash('sha256',($_SERVER['HTTP_USER_AGENT']??'').'|'.(getenv('APP_KEY')?:'local'))]);$this->db->commit();}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();error_log($e->__toString());}header('Content-Type: application/pdf');header('Content-Length: '.filesize($file));header('Content-Disposition: attachment; filename="'.self::safeFilename($brochure['original_filename']?:$brochure['title'].'.pdf').'"');header('X-Content-Type-Options: nosniff');readfile($file);exit;
    }

    private function redirectLegacyBrochure(): never
    {
        $id=$_GET['id']??null;
        $query=is_scalar($id)&&trim((string)$id)!==''?'?'.http_build_query(['id'=>(string)$id],'','&',PHP_QUERY_RFC3986):'';
        header('Location: /api/brochure'.$query,true,301);
        exit;
    }

