    private function admin(string $path,string $method): void
    {
        header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
        header('Pragma: no-cache');
        $user=$this->authenticatedAdmin();if(!$user){$this->adminLogin($method);return;}
        if($path==='/admin/logout'){
            if($method!=='POST'){$this->methodNotAllowed(['POST']);return;}$this->checkCsrf();$_SESSION=[];if(ini_get('session.use_cookies')){$params=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$params['path'],$params['domain'],$params['secure'],$params['httponly']);}session_destroy();header('Location: /admin');return;
        }
        if($path==='/admin/quotes'){$this->adminQuotes();return;}
        if($path==='/admin/quote'&&$method==='POST'){$this->saveQuoteStatus((int)$user['id']);return;}
        if($path==='/admin/quote'){$this->adminQuote((int)($_GET['id']??0));return;}
        if($path==='/admin/enquiries'){$this->adminEnquiries();return;}
        if($path==='/admin/enquiry'&&$method==='POST'){$this->saveEnquiryStatus((int)$user['id']);return;}
        if($path==='/admin/enquiry'){$this->adminEnquiry((int)($_GET['id']??0));return;}
        if($path==='/admin/product'&&$method==='POST'){$id=(int)($_POST['id']??0);try{$this->saveProduct((int)$user['id']);}catch(DomainException $e){$this->adminProduct($id,$e->getMessage(),$_POST);}return;}
        if($path==='/admin/product'){$this->adminProduct((int)($_GET['id']??0));return;}
        if($path==='/admin/category'&&$method==='POST'){try{$this->saveCategory((int)$user['id']);}catch(DomainException $e){$this->adminCategories((int)($_POST['id']??0),$e->getMessage(),$_POST);}return;}
        if($path==='/admin/categories'){$this->adminCategories((int)($_GET['id']??0));return;}
        if($path==='/admin/confirmations'){$this->adminConfirmations();return;}
        if($path==='/admin/confirmation'&&$method==='POST'){$this->saveConfirmation();return;}
        if($path==='/admin/confirmation'){$this->adminConfirmation((int)($_GET['id']??0));return;}
        if($path==='/admin/recaptcha'&&$method==='GET'){$this->json(['enabled'=>$this->captcha->siteKey()!==null,'site_key'=>$this->captcha->siteKey()]);}
        if($path==='/admin/recaptcha'&&$method==='POST'){$this->checkApiCsrf($this->input());$this->json(['message'=>'CAPTCHA secrets are configured only through the private environment file.']);}
        $rows=$this->db->query("SELECT p.id,p.name,p.sku,p.status,p.visibility,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();$table='';foreach($rows as $row)$table.='<tr><td>'.(int)$row['id'].'</td><td><a href="/admin/product?id='.(int)$row['id'].'">'.self::e($row['name']).'</a></td><td>'.self::e($row['sku']).'</td><td>'.self::e($row['category_name']??'').'</td><td>'.self::e($row['status'].' / '.$row['visibility']).'</td></tr>';$this->layout('Catalogue admin','<section class="fd-page fd-admin"><div class="fd-admin-head"><h1>Catalogue admin</h1><div><a href="/admin/product">Create product</a> · <a href="/admin/categories">Categories</a> · <a href="/admin/quotes">Quotes</a> · <a href="/admin/enquiries">Enquiries</a> · <a href="/admin/confirmations">Confirmations</a> · '.$this->logoutForm().'</div></div><div class="fd-table-wrap"><table><thead><tr><th>ID</th><th>Product</th><th>SKU</th><th>Category</th><th>Status</th></tr></thead><tbody>'.$table.'</tbody></table></div></section>');
    }

    private function authenticatedAdmin(): ?array
    {
        if(empty($_SESSION['admin_user_id']))return null;$stmt=$this->db->prepare("SELECT id,role,status,session_version,first_name,last_name,email FROM users WHERE id=? LIMIT 1");$stmt->execute([(int)$_SESSION['admin_user_id']]);$user=$stmt->fetch();$valid=$user&&$user['status']==='active'&&in_array($user['role'],['admin','super_admin'],true)&&(int)$user['session_version']===(int)($_SESSION['session_version']??0);if(!$valid){$_SESSION=[];return null;}$_SESSION['last_activity']=time();return $user;
    }

    private function adminLogin(string $method): void
    {
        $error='';if($method==='POST'){$this->checkCsrf();$identity=strtolower(trim((string)($_POST['email']??'')));$key=$this->authRateKey($identity);if($this->loginBlocked($key))$error='Too many sign-in attempts. Try again in 15 minutes.';else{$stmt=$this->db->prepare("SELECT id,password_hash,role,status,session_version FROM users WHERE email=? LIMIT 1");$stmt->execute([$identity]);$user=$stmt->fetch();if($user&&$user['status']==='active'&&in_array($user['role'],['admin','super_admin'],true)&&password_verify((string)($_POST['password']??''),(string)$user['password_hash'])){$this->recordLoginAttempt($key,true);session_regenerate_id(true);$_SESSION['admin_user_id']=(int)$user['id'];$_SESSION['session_version']=(int)$user['session_version'];$_SESSION['session_started']=time();$_SESSION['last_activity']=time();header('Location: /admin');return;}$this->recordLoginAttempt($key,false);$error='Invalid sign-in details.';}}
        $this->layout('Admin sign in','<section class="fd-page fd-admin"><h1>Admin sign in</h1>'.($error?'<p class="fd-error">'.self::e($error).'</p>':'').'<form method="post"><input type="hidden" name="csrf" value="'.self::e($this->csrf()).'"><label>Email<input type="email" name="email" maxlength="190" required></label><label>Password<input type="password" name="password" maxlength="255" required></label><button class="fd-btn">Sign in</button></form></section>');
    }

    private function adminQuotes(): void
    {
        $q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$where=['1=1'];$params=[];
        if($q!==''){$where[]='(quote_number LIKE ? OR full_name LIKE ? OR company LIKE ? OR email LIKE ? OR phone LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term,$term,$term);}
        if($status!==''){$where[]='status=?';$params[]=$status;}
        $stmt=$this->db->prepare("SELECT id,quote_number,status,full_name,company,email,phone,pricing_status,has_confirmed_amount,total,submitted_at FROM quote_requests WHERE ".implode(' AND ',$where)." ORDER BY submitted_at DESC LIMIT 200");$stmt->execute($params);$rows='';
        foreach($stmt->fetchAll() as $row){$pricing=!$row['has_confirmed_amount']?'Price pending':($row['pricing_status']==='price_pending'?'Price pending · confirmed '.self::money($row['total']):self::money($row['total']));$rows.='<tr><td><a href="/admin/quote?id='.(int)$row['id'].'">'.self::e($row['quote_number']).'</a></td><td>'.self::e($row['full_name']).($row['company']?'<br><small>'.self::e($row['company']).'</small>':'').'<br><small>'.self::e($row['email'].' · '.$row['phone']).'</small></td><td>'.self::e($row['status']).'</td><td>'.$pricing.'</td><td>'.self::e($row['submitted_at']).'</td></tr>';}
        $this->layout('Quotes','<section class="fd-page fd-admin"><a href="/admin">← Catalogue</a><h1>Quotes</h1><form method="get" class="fd-admin-filters"><label>Search<input name="q" value="'.self::e($q).'" maxlength="190"></label><label>Status<input name="status" value="'.self::e($status).'" maxlength="40"></label><button class="fd-btn">Search</button></form><div class="fd-table-wrap"><table><thead><tr><th>Reference</th><th>Customer and company</th><th>Status</th><th>Pricing</th><th>Date</th></tr></thead><tbody>'.$rows.'</tbody></table></div></section>');
    }

    private function adminQuote(int $id): void
    {
        $stmt=$this->db->prepare("SELECT * FROM quote_requests WHERE id=?");$stmt->execute([$id]);$quote=$stmt->fetch();if(!$quote){$this->notFound();return;}
        $itemsStmt=$this->db->prepare("SELECT * FROM quote_items WHERE quote_id=? ORDER BY sort_order,id");$itemsStmt->execute([$id]);$items='';
        foreach($itemsStmt->fetchAll() as $item){
            $parts=[];foreach((array)(json_decode($item['variation_snapshot']?:'{}',true)?:[]) as $label=>$value)$parts[]=ucwords(str_replace('_',' ',(string)$label)).': '.$value;
            foreach((array)(json_decode($item['selected_options_json']?:'[]',true)?:[]) as $option)if(is_array($option))$parts[]=($option['group_label']??'Option').': '.($option['label']??$option['code']??'');
            $pending=[];foreach((array)(json_decode($item['pending_price_components_json']?:'[]',true)?:[]) as $component)if(is_array($component))$pending[]=$component['label']??'Price component';
            $configuration=implode(' · ',array_filter($parts));$amount=$item['confirmed_line_total']===null?'Price pending':self::money($item['confirmed_line_total']);
            if($pending)$amount='Price pending'.($item['confirmed_line_total']!==null?' · confirmed '.self::money($item['confirmed_line_total']):'').' ('.self::e(implode(', ',$pending)).')';
            $items.='<tr><td>'.self::e($item['product_name']).'<br><small>'.self::e($item['sku']??'').($configuration?'<br>'.self::e($configuration):'').'</small></td><td>'.(int)$item['quantity'].'</td><td>'.$amount.'</td></tr>';
        }
        $historyStmt=$this->db->prepare("SELECT * FROM quote_history WHERE quote_id=? ORDER BY created_at DESC,id DESC");$historyStmt->execute([$id]);$history='';foreach($historyStmt->fetchAll() as $row)$history.='<li><strong>'.self::e($row['status']).'</strong> — '.self::e($row['summary']??$row['event_type']).' <small>'.self::e($row['created_at']).'</small></li>';
        $pricing=!$quote['has_confirmed_amount']?'<strong>Confirmed amount:</strong> Price pending.':'<strong>Confirmed subtotal:</strong> '.self::money($quote['subtotal']).'<br>'.(!empty($quote['tax_enabled'])?'<strong>Configured tax ('.self::e((string)$quote['vat_rate']).'%):</strong> '.self::money($quote['vat_amount']).'<br>':'<strong>Tax:</strong> Disabled; Product Guide prices used as supplied.<br>').'<strong>Confirmed total:</strong> '.self::money($quote['total']);
        $this->layout('Quote '.$quote['quote_number'],'<section class="fd-page fd-admin"><a href="/admin/quotes">← Quotes</a><h1>'.self::e($quote['quote_number']).'</h1><p><strong>Date:</strong> '.self::e($quote['submitted_at']).'<br><strong>Status:</strong> '.self::e($quote['status']).'<br><strong>Customer:</strong> '.self::e($quote['full_name']).'<br><strong>Company:</strong> '.self::e($quote['company']?:'Not supplied').'<br><strong>Email:</strong> '.self::e($quote['email']).'<br><strong>Phone:</strong> '.self::e($quote['phone']).'<br><strong>Range:</strong> '.self::e($quote['interest']??'').'</p><p><strong>Address:</strong> '.self::e(implode(', ',array_filter([$quote['address_line'],$quote['suburb'],$quote['city'],$quote['province'],$quote['postal_code'],$quote['country']]))).'</p><p><strong>Customer notes and selected colours:</strong><br>'.nl2br(self::e($quote['customer_notes']?:'None supplied')).'</p><div class="fd-table-wrap"><table><thead><tr><th>Product, variation and selected options</th><th>Quantity</th><th>Confirmed and pending amounts</th></tr></thead><tbody>'.$items.'</tbody></table></div><p>'.$pricing.'</p><p>Delivery and installation are quoted separately.</p><form method="post" action="/admin/quote"><input type="hidden" name="csrf" value="'.self::e($this->csrf()).'"><input type="hidden" name="id" value="'.$id.'"><label>Status<select name="status">'.$this->selectOptions(['new_enquiry','in_progress','quoted','sent','accepted','declined','closed'],$quote['status']).'</select></label><label class="fd-wide">History note<input name="summary" maxlength="500" required></label><button class="fd-btn">Update status</button></form><h2>Status history</h2><ol>'.$history.'</ol></section>');
    }

    private function saveQuoteStatus(int $adminId): void
