    private function syncAdminVariations(int $productId,array $variations,string $productType): void
    {
        if($productType==='simple'){$this->db->prepare("UPDATE product_variations SET enabled=0 WHERE product_id=?")->execute([$productId]);return;}$retained=[];foreach($variations as $variation){if(!is_array($variation)||!is_array($variation['attributes']??null))throw new DomainException('Each variation needs an attributes object.');$regular=$variation['regular_price']??null;$sale=$variation['sale_price']??null;if($regular===null||(float)$regular<0||$sale!==null&&(float)$sale<0)throw new DomainException('Variation prices must be valid and non-negative.');if($sale!==null&&(float)$sale>(float)$regular)throw new DomainException('A variation sale price cannot exceed its regular price.');$stock=$variation['stock_status']??'in_stock';if(!in_array($stock,['in_stock','out_of_stock','on_backorder'],true))throw new DomainException('A variation has an invalid stock status.');$sku=trim((string)($variation['sku']??''));if($sku!==''){$duplicate=$this->db->prepare("SELECT COUNT(*) FROM product_variations WHERE sku=? AND id<>?");$duplicate->execute([$sku,(int)($variation['id']??0)]);if((int)$duplicate->fetchColumn())throw new DomainException('A variation SKU is already in use.');}$values=[$sku?:null,$regular,$sale,$stock,(int)($variation['position']??0),json_encode($variation['attributes'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),!empty($variation['enabled'])?1:0];if(!empty($variation['id'])){$id=(int)$variation['id'];$this->db->prepare("UPDATE product_variations SET sku=?,regular_price=?,sale_price=?,stock_status=?,position=?,attributes_json=?,enabled=?,updated_at=NOW() WHERE id=? AND product_id=?")->execute([...$values,$id,$productId]);$retained[]=$id;}else{$this->db->prepare("INSERT INTO product_variations(product_id,source_system,sku,regular_price,sale_price,stock_status,position,attributes_json,enabled) VALUES(?,'admin',?,?,?,?,?,?,?)")->execute([$productId,...$values]);$retained[]=(int)$this->db->lastInsertId();}}$sql="UPDATE product_variations SET enabled=0 WHERE product_id=?";$params=[$productId];if($retained){$sql.=' AND id NOT IN ('.implode(',',array_fill(0,count($retained),'?')).')';array_push($params,...$retained);}$this->db->prepare($sql)->execute($params);
    }

    private function syncAdminOptions(int $productId,array $groups): void
    {
        $groupIds=[];foreach($groups as $group){$code=trim((string)($group['code']??''));$label=trim((string)($group['label']??''));if($code===''||$label==='')throw new DomainException('Each option group needs a code and label.');$type=in_array($group['type']??'',['single','multiple','display'],true)?$group['type']:'single';$metadata=json_encode((array)($group['metadata']??[]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$stmt=$this->db->prepare("INSERT INTO product_option_groups(product_id,option_code,public_label,selection_type,is_required,is_active,display_order,metadata_json) VALUES(?,?,?,?,?,1,?,?) ON DUPLICATE KEY UPDATE public_label=VALUES(public_label),selection_type=VALUES(selection_type),is_required=VALUES(is_required),is_active=1,display_order=VALUES(display_order),metadata_json=VALUES(metadata_json),id=LAST_INSERT_ID(id)");$stmt->execute([$productId,$code,$label,$type,!empty($group['required'])?1:0,(int)($group['display_order']??0),$metadata]);$groupId=(int)$this->db->lastInsertId();$groupIds[]=$groupId;$valueIds=[];foreach((array)($group['values']??[]) as $value){$valueCode=trim((string)($value['code']??''));$valueLabel=trim((string)($value['label']??''));if($valueCode===''||$valueLabel==='')throw new DomainException('Each option value needs a code and label.');$mode=in_array($value['pricing_mode']??'',['included','fixed','additive','request_quote'],true)?$value['pricing_mode']:'included';$price=$mode==='request_quote'?null:($value['price_adjustment']??0);if($price!==null&&(float)$price<0)throw new DomainException('Option prices cannot be negative.');$valueStmt=$this->db->prepare("INSERT INTO product_option_values(option_group_id,value_code,public_label,price_adjustment,pricing_mode,is_default,is_active,display_order,conditions_json,metadata_json) VALUES(?,?,?,?,?,?,1,?,?,?) ON DUPLICATE KEY UPDATE public_label=VALUES(public_label),price_adjustment=VALUES(price_adjustment),pricing_mode=VALUES(pricing_mode),is_default=VALUES(is_default),is_active=1,display_order=VALUES(display_order),conditions_json=VALUES(conditions_json),metadata_json=VALUES(metadata_json),id=LAST_INSERT_ID(id)");$valueStmt->execute([$groupId,$valueCode,$valueLabel,$price,$mode,!empty($value['default'])?1:0,(int)($value['display_order']??0),json_encode((array)($value['conditions']??[]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),json_encode((array)($value['metadata']??[]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$valueIds[]=(int)$this->db->lastInsertId();}$sql="UPDATE product_option_values SET is_active=0 WHERE option_group_id=?";$params=[$groupId];if($valueIds){$sql.=' AND id NOT IN ('.implode(',',array_fill(0,count($valueIds),'?')).')';array_push($params,...$valueIds);}$this->db->prepare($sql)->execute($params);}$sql="UPDATE product_option_groups SET is_active=0 WHERE product_id=?";$params=[$productId];if($groupIds){$sql.=' AND id NOT IN ('.implode(',',array_fill(0,count($groupIds),'?')).')';array_push($params,...$groupIds);}$this->db->prepare($sql)->execute($params);
    }

    private function syncProductMedia(int $productId,array $mediaIds,?int $thumbnail): void{if($thumbnail&&!in_array($thumbnail,$mediaIds,true))array_unshift($mediaIds,$thumbnail);foreach($mediaIds as $mediaId){$stmt=$this->db->prepare("SELECT COUNT(*) FROM media_assets WHERE id=?");$stmt->execute([$mediaId]);if(!(int)$stmt->fetchColumn())throw new DomainException('Gallery contains an invalid media selection.');}$this->db->prepare("DELETE FROM product_media WHERE product_id=?")->execute([$productId]);$stmt=$this->db->prepare("INSERT INTO product_media(product_id,media_id,sort_order,is_primary) VALUES(?,?,?,?)");foreach($mediaIds as $order=>$mediaId)$stmt->execute([$productId,$mediaId,$order,$thumbnail===$mediaId?1:0]);}
    private function productHasQuoteStrategy(int $id): bool{$stmt=$this->db->prepare("SELECT COUNT(*) FROM product_option_values v JOIN product_option_groups g ON g.id=v.option_group_id WHERE g.product_id=? AND g.is_active=1 AND v.is_active=1 AND v.pricing_mode='request_quote'");$stmt->execute([$id]);return(bool)$stmt->fetchColumn();}

    private function adminCategories(int $id,string $error='',?array $posted=null): void
    {
        if($id){$stmt=$this->db->prepare("SELECT * FROM categories WHERE id=?");$stmt->execute([$id]);$category=$stmt->fetch();if(!$category){$this->notFound();return;}}else$category=['id'=>0,'name'=>'','slug'=>'','parent_id'=>null,'sort_order'=>0,'is_active'=>1];if($posted)$category=array_merge($category,$posted);$rows=$this->db->query("SELECT c.id,c.name,c.slug,c.parent_id,c.sort_order,c.is_active,p.name parent_name,(SELECT COUNT(*) FROM products pr WHERE pr.category_id=c.id) product_count FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY COALESCE(c.parent_id,0),c.sort_order,c.name")->fetchAll();$table='';$parents='<option value="">Top level (protected)</option>';foreach($rows as $row){$table.='<tr><td><a href="/admin/categories?id='.(int)$row['id'].'">'.self::e($row['name']).'</a></td><td>'.self::e($row['slug']).'</td><td>'.self::e($row['parent_name']??'Top level').'</td><td>'.(int)$row['product_count'].'</td><td>'.(!empty($row['is_active'])?'Active':'Inactive').'</td></tr>';if($row['parent_id']===null&&(int)$row['id']!==$id)$parents.='<option value="'.(int)$row['id'].'"'.((int)($category['parent_id']??0)===(int)$row['id']?' selected':'').'>'.self::e($row['name']).'</option>';}$form='<form method="post" action="/admin/category"><input type="hidden" name="csrf" value="'.self::e($this->csrf()).'"><input type="hidden" name="id" value="'.$id.'"><label>Name<input name="name" maxlength="190" value="'.self::e((string)$category['name']).'" required></label><label>Slug<input name="slug" maxlength="190" value="'.self::e((string)$category['slug']).'" required></label><label>Parent<select name="parent_id">'.$parents.'</select></label><label>Sort order<input type="number" name="sort_order" value="'.(int)$category['sort_order'].'"></label><label><input type="checkbox" name="is_active" value="1"'.(!empty($category['is_active'])?' checked':'').'> Active</label><button class="fd-btn fd-wide">Save category</button></form>';$this->layout('Categories','<section class="fd-page fd-admin"><a href="/admin">← Catalogue</a><h1>Categories</h1>'.($error?'<p class="fd-error">'.self::e($error).'</p>':'').(isset($_GET['saved'])?'<p class="fd-success">Category saved.</p>':'').$form.'<div class="fd-table-wrap"><table><thead><tr><th>Category</th><th>Slug</th><th>Parent</th><th>Products</th><th>Status</th></tr></thead><tbody>'.$table.'</tbody></table></div></section>');
    }

    private function saveCategory(int $adminId): void
    {
        $this->checkCsrf();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$slug=trim((string)($_POST['slug']??''));$parentId=(int)($_POST['parent_id']??0)?:null;$sort=(int)($_POST['sort_order']??0);$active=!empty($_POST['is_active'])?1:0;
        if($name===''||strlen($name)>190||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug))throw new DomainException('A category name and lowercase hyphenated slug are required.');
        $protected=[
            'pizza-ovens'=>['name'=>'Pizza Ovens','parent'=>null],'accessories'=>['name'=>'Accessories','parent'=>null],'fireplace'=>['name'=>'Fireplace','parent'=>null],
            'domestic'=>['name'=>'Domestic','parent'=>'pizza-ovens'],'mobile'=>['name'=>'Mobile','parent'=>'pizza-ovens'],'commercial'=>['name'=>'Commercial','parent'=>'pizza-ovens'],
            'pizza-oven-utensils-accessories'=>['name'=>'Pizza Oven Utensils & Accessories','parent'=>'accessories'],'canvas-covers'=>['name'=>'Canvas Covers','parent'=>'accessories'],
        ];
        $old=null;if($id){$stmt=$this->db->prepare("SELECT c.*,p.slug parent_slug FROM categories c LEFT JOIN categories p ON p.id=c.parent_id WHERE c.id=?");$stmt->execute([$id]);$old=$stmt->fetch();if(!$old)throw new DomainException('Category not found.');}
        $parent=null;if($parentId){if($parentId===$id)throw new DomainException('A category cannot be its own parent.');$stmt=$this->db->prepare("SELECT slug,parent_id,is_active FROM categories WHERE id=?");$stmt->execute([$parentId]);$parent=$stmt->fetch();if(!$parent||!$parent['is_active']||$parent['parent_id']!==null)throw new DomainException('Choose an active top-level parent. Category depth is limited to two levels.');}
        $protectedSlug=$old['slug']??$slug;if(isset($protected[$protectedSlug])){$rule=$protected[$protectedSlug];$parentSlug=$parent['slug']??null;if($slug!==$protectedSlug||$name!==$rule['name']||$parentSlug!==$rule['parent']||!$active)throw new DomainException('Protected categories must keep their approved name, slug, parent and active status.');}
        elseif($parentId===null)throw new DomainException('Exactly three active top-level categories are allowed. New categories must be children of an active top-level category.');
        $duplicate=$this->db->prepare("SELECT COUNT(*) FROM categories WHERE slug=? AND id<>?");$duplicate->execute([$slug,$id]);if((int)$duplicate->fetchColumn())throw new DomainException('The category slug is already in use.');
        $this->db->beginTransaction();try{
            if($id){$oldPath=($old['parent_slug']?$old['parent_slug'].'/':'').$old['slug'];$newParentSlug=$parent['slug']??null;$newPath=($newParentSlug?$newParentSlug.'/':'').$slug;$this->db->prepare("UPDATE categories SET name=?,slug=?,parent_id=?,sort_order=?,is_active=?,updated_at=NOW() WHERE id=?")->execute([$name,$slug,$parentId,$sort,$active,$id]);if($oldPath!==$newPath)$this->db->prepare("INSERT INTO category_slug_redirects(category_id,old_parent_slug,old_slug,new_parent_slug,new_slug,old_path,new_path,redirect_code,is_active) VALUES(?,?,?,?,?,?,?,301,1) ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),new_parent_slug=VALUES(new_parent_slug),new_slug=VALUES(new_slug),new_path=VALUES(new_path),is_active=1")->execute([$id,$old['parent_slug'],$old['slug'],$newParentSlug,$slug,$oldPath,$newPath]);}
            else{$this->db->prepare("INSERT INTO categories(name,slug,parent_id,sort_order,is_active) VALUES(?,?,?,?,?)")->execute([$name,$slug,$parentId,$sort,$active]);$id=(int)$this->db->lastInsertId();}
            $this->writeAudit($adminId,'category_saved','category',$id,$name);$this->db->commit();
        }catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}header('Location: /admin/categories?id='.$id.'&saved=1');return;
    }

    private function adminConfirmations(): void{$status=in_array($_GET['status']??'',['pending','confirmed','rejected','replaced'],true)?$_GET['status']:'pending';$stmt=$this->db->prepare("SELECT pc.*,p.name product_name FROM product_confirmations pc LEFT JOIN products p ON p.id=pc.product_id WHERE pc.status=? ORDER BY pc.requires_price_update DESC,pc.requires_image DESC,pc.internal_title");$stmt->execute([$status]);$rows='';foreach($stmt->fetchAll() as $row)$rows.='<tr><td><a href="/admin/confirmation?id='.(int)$row['id'].'">'.self::e($row['internal_title']).'</a></td><td>'.self::e($row['product_name']??'General').'</td><td>'.self::e($row['status']).'</td></tr>';$this->layout('Confirmation register','<section class="fd-page fd-admin"><a href="/admin">← Catalogue</a><h1>Confirmation register</h1><div class="fd-table-wrap"><table><thead><tr><th>Issue</th><th>Product</th><th>Status</th></tr></thead><tbody>'.$rows.'</tbody></table></div></section>');}
    private function adminConfirmation(int $id): void{$stmt=$this->db->prepare("SELECT pc.*,p.name product_name FROM product_confirmations pc LEFT JOIN products p ON p.id=pc.product_id WHERE pc.id=?");$stmt->execute([$id]);$row=$stmt->fetch();if(!$row){$this->notFound();return;}$historyStmt=$this->db->prepare("SELECT h.*,CONCAT(u.first_name,' ',u.last_name) changed_by FROM product_confirmation_history h LEFT JOIN users u ON u.id=h.changed_by_user_id WHERE h.confirmation_id=? ORDER BY h.changed_at DESC");$historyStmt->execute([$id]);$history='';foreach($historyStmt->fetchAll() as $item)$history.='<li>'.self::e($item['old_status'].' → '.$item['new_status'].' · '.($item['changed_by']?:'System').' · '.$item['change_note']).'</li>';$this->layout('Confirmation','<section class="fd-page fd-admin"><a href="/admin/confirmations">← Confirmations</a><h1>'.self::e($row['internal_title']).'</h1><p><strong>Issue:</strong> '.self::e($row['issue_description']).'</p><p><strong>Provisional value:</strong> '.self::e((string)$row['provisional_value']).'</p><p><strong>Public handling:</strong> '.self::e($row['public_handling']).'</p><form method="post" action="/admin/confirmation"><input type="hidden" name="csrf" value="'.self::e($this->csrf()).'"><input type="hidden" name="id" value="'.$id.'"><label>Status<select name="status">'.$this->selectOptions(['pending','confirmed','rejected','replaced'],$row['status']).'</select></label><label>Confirmed value<textarea name="confirmed_value">'.self::e((string)$row['confirmed_value']).'</textarea></label><label>Confirmed by<input name="confirmed_by" maxlength="190" value="'.self::e((string)$row['confirmed_by']).'"></label><label>Date<input type="date" name="confirmation_date" value="'.self::e((string)$row['confirmation_date']).'"></label><label class="fd-wide">Internal notes<textarea name="internal_notes" maxlength="10000">'.self::e((string)$row['internal_notes']).'</textarea></label><label class="fd-wide">Audit note<input name="change_note" maxlength="500" required></label><button class="fd-btn fd-wide">Save</button></form><h2>History</h2><ol>'.$history.'</ol></section>');}
    private function saveConfirmation(): void{$this->checkCsrf();$id=(int)($_POST['id']??0);$status=in_array($_POST['status']??'',['pending','confirmed','rejected','replaced'],true)?$_POST['status']:'pending';$confirmedBy=trim((string)($_POST['confirmed_by']??''));$date=trim((string)($_POST['confirmation_date']??''));$note=trim((string)($_POST['change_note']??''));if(!$id||$note==='')throw new DomainException('A confirmation and audit note are required.');if($status!=='pending'&&($confirmedBy===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)))throw new DomainException('Resolved items require who confirmed them and a valid date.');$this->db->beginTransaction();try{$stmt=$this->db->prepare("SELECT status,confirmed_value FROM product_confirmations WHERE id=? FOR UPDATE");$stmt->execute([$id]);$old=$stmt->fetch();if(!$old)throw new DomainException('Confirmation not found.');$value=trim((string)($_POST['confirmed_value']??''));$this->db->prepare("UPDATE product_confirmations SET status=?,confirmed_value=NULLIF(?,''),confirmed_by=NULLIF(?,''),confirmation_date=NULLIF(?,''),internal_notes=?,updated_at=NOW() WHERE id=?")->execute([$status,$value,$confirmedBy,$date,trim((string)($_POST['internal_notes']??'')),$id]);$this->db->prepare("INSERT INTO product_confirmation_history(confirmation_id,old_status,new_status,old_confirmed_value,new_confirmed_value,changed_by_user_id,change_note) VALUES(?,?,?,?,?,?,?)")->execute([$id,$old['status'],$status,$old['confirmed_value'],$value,(int)$_SESSION['admin_user_id'],$note]);$this->db->commit();}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}header('Location: /admin/confirmation?id='.$id);return;}

    private function writeAudit(int $adminId,string $action,string $entity,int $id,string $summary): void{$stmt=$this->db->prepare("INSERT INTO audit_logs(id,admin_id,action,entity_type,entity_id,ip_address,user_agent,safe_summary) VALUES(?,?,?,?,?,?,?,?)");$stmt->execute([bin2hex(random_bytes(16)),(string)$adminId,$action,$entity,(string)$id,null,null,substr($summary,0,500)]);}

    private function cards(array $products): string{if(!$products)return'<p>No products match these filters.</p>';$html='';foreach($products as $product){$min=$product['min_variation_price']??null;$max=$product['max_variation_price']??null;$price=$min!==null?((float)$min===(float)$max?self::money($min):self::money($min).'–'.self::money($max)):(($product['sale_price']??$product['regular_price']??null)!==null?self::money($product['sale_price']??$product['regular_price']):'Request a quote');$stock=$product['stock_status']==='out_of_stock'?'<span class="fd-stock-label">Out of stock</span>':'';$html.='<article class="fd-card"><a href="/product/'.rawurlencode($product['slug']).'"><img loading="lazy" src="'.self::e($product['image_url']).'" alt="'.self::e($product['name']).'"><div><p class="fd-category-path">'.self::e(trim(($product['parent_category_name']??'').' › '.($product['category_name']??''),' ›')).'</p><h3>'.self::e($product['name']).'</h3><p class="fd-price">'.$price.'</p>'.$stock.'<span class="fd-card-action">View product →</span></div></a></article>'; }return$html;}
    private function renderSpecifications(array $data): string{$html='';if(isset($data['models'])&&is_array($data['models'])){$columns=is_array($data['columns']??null)?$data['columns']:[];$html.='<div class="fd-table-wrap"><table><thead><tr>';foreach($columns as $column)$html.='<th scope="col">'.self::e((string)($column['label']??$column['key']??'')).'</th>';$html.='</tr></thead><tbody>';foreach($data['models'] as $model){$html.='<tr>';foreach($columns as $column)$html.='<td>'.self::e((string)($model[$column['key']??'']??'')).'</td>';$html.='</tr>';}$html.='</tbody></table></div>';}$skip=['layout','columns','models','fields'];$list='';foreach((array)($data['fields']??[]) as $field){if(!is_array($field))continue;$label=trim((string)($field['label']??''));$value=$field['value']??'';if($label!==''&&is_scalar($value)&&trim((string)$value)!=='')$list.='<div><dt>'.self::e($label).'</dt><dd>'.self::e((string)$value).'</dd></div>';}foreach($data as $key=>$value){if(in_array($key,$skip,true))continue;$label=ucwords(str_replace('_',' ',(string)$key));if(is_array($value)){if(array_is_list($value))$rendered=implode(', ',array_map(fn($item)=>is_scalar($item)?(string)$item:json_encode($item),$value));else{$parts=[];foreach($value as $childKey=>$childValue)$parts[]=ucwords(str_replace('_',' ',(string)$childKey)).': '.(is_array($childValue)?implode(', ',array_map('strval',$childValue)):(string)$childValue);$rendered=implode('; ',$parts);}}else$rendered=(string)$value;if($rendered!=='')$list.='<div><dt>'.self::e($label).'</dt><dd>'.self::e($rendered).'</dd></div>';}$html.=$list?'<dl class="fd-spec-list">'.$list.'</dl>':'';return$html;}
    private function pagination(array $pagination,string $canonical): string{if($pagination['pages']<2)return'';$html='<nav class="fd-pagination" aria-label="Product pages">';for($page=1;$page<=$pagination['pages'];$page++)$html.='<a'.($page===$pagination['page']?' aria-current="page"':'').' href="'.$canonical.'?page='.$page.'">'.$page.'</a>';return$html.'</nav>';}

    private function layout(string $title,string $body,int $status=200,string $description='',?string $canonicalPath=null,?array $jsonLd=null): void
    {
        http_response_code($status);header('Content-Type: text/html; charset=utf-8');$nonce=base64_encode(random_bytes(18));header("Content-Security-Policy: default-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; object-src 'none'; img-src 'self' data: https:; style-src 'self' https://fonts.googleapis.com; script-src 'self' 'nonce-{$nonce}' https://www.googletagmanager.com https://www.google-analytics.com https://www.google.com https://www.gstatic.com; connect-src 'self' https://www.google-analytics.com https://www.googletagmanager.com https://www.google.com https://www.gstatic.com; font-src 'self' data: https://fonts.gstatic.com; frame-src https://www.google.com https://www.gstatic.com https://www.youtube.com https://player.vimeo.com; upgrade-insecure-requests");$base=rtrim(getenv('APP_URL')?:'https://www.fireanddine.co.za','/');$canonical=$base.($canonicalPath??(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/'));$description=substr(trim($description?:'Fire & Dine wood-fired pizza ovens, accessories and fireplaces.'),0,160);$fullTitle=str_ends_with(strtolower(trim($title)),'| fire & dine')?$title:$title.' | Fire & Dine';
        echo '<!doctype html><html lang="en-ZA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($fullTitle).'</title><meta name="description" content="'.self::e($description).'"><link rel="canonical" href="'.self::e($canonical).'"><meta property="og:title" content="'.self::e($fullTitle).'"><meta property="og:description" content="'.self::e($description).'"><meta property="og:type" content="website"><link rel="icon" href="/assets/images/favicon.png"><link rel="stylesheet" href="/assets/css/design-system.css"><link rel="stylesheet" href="/assets/css/fire-dine-premium.css"><link rel="stylesheet" href="/assets/css/storefront-phase-5-7.css">'.($jsonLd?'<script nonce="'.self::e($nonce).'" type="application/ld+json">'.json_encode($jsonLd,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).'</script>':'').'</head><body><a class="fd-skip" href="#main">Skip to content</a><header class="fd-header"><a class="fd-logo" href="/"><img src="/assets/images/logo/fire-dine-header-logo.png" alt="Fire &amp; Dine"></a><button class="fd-menu" type="button" aria-expanded="false" aria-controls="main-nav">Menu</button><nav id="main-nav" aria-label="Main navigation"><a href="/">Home</a><a href="/category/pizza-ovens">Pizza Ovens</a><a href="/category/accessories">Accessories</a><a href="/category/fireplace">Fireplace</a><a href="/installation">Installation</a><a href="/gallery">Gallery</a><a href="/contact">Contact</a><a class="fd-quote-link" href="/cart">Quote <span data-basket-count>0</span></a></nav></header><main id="main">'.$body.'</main><footer class="fd-footer"><img src="/assets/images/logo/fire-dine-footer-logo.webp" alt="Fire &amp; Dine"><p>Wood-fired cooking, made in South Africa.</p><p><a href="tel:+27834381485">083 438 1485</a> · <a href="tel:+27160130411">016 013 0411</a><br><a href="mailto:info@fireanddine.co.za">info@fireanddine.co.za</a><br>Springbok Ave, Ardenwold AH, Vanderbijlpark, 1911</p><nav aria-label="Footer"><a href="/about">About</a><a href="/shop">Shop</a><a href="/faq">FAQ</a><a href="/privacy-policy">Privacy</a><a href="/terms-of-service">Terms</a>'.$this->brochureLink().'</nav></footer><script src="/assets/js/basket-calculations.js" defer></script><script src="/assets/js/storefront-phase-5-7.js" defer></script>'.($this->captcha->siteKey()?'<script src="https://www.google.com/recaptcha/api.js" async defer></script>':'').'</body></html>';
    }

    private function input(): array{$raw=file_get_contents('php://input')?:'';if(strlen($raw)>1048576)throw new DomainException('Request body is too large.');$data=json_decode($raw,true);return is_array($data)?$data:$_POST;}
    private function brochureLink(): string{$row=$this->db->query("SELECT id,button_text FROM brochures WHERE enabled=1 ORDER BY display_footer DESC,id LIMIT 1")->fetch();return$row?'<a href="/brochure/'.(int)$row['id'].'">'.self::e($row['button_text']?:'Brochure').'</a>':'';}
    private function json(array $data,int $status=200,array $headers=[]): never{http_response_code($status);foreach($headers as $name=>$value)header($name.': '.$value);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
    private function csrf(): string{$_SESSION['csrf']??=bin2hex(random_bytes(32));return$_SESSION['csrf'];}
    private function checkCsrf(): void{if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))throw new DomainException('Your session expired. Refresh and try again.');}
    private function checkApiCsrf(array $input): void{$provided=(string)($_SERVER['HTTP_X_CSRF_TOKEN']??($input['csrf_token']??''));if(!hash_equals($_SESSION['csrf']??'',$provided))throw new DomainException('Your session expired. Refresh and try again.');}
    private function cleanHtml(string $value): string{$value=preg_replace('#<(script|style)[^>]*>.*?</\1>#is','',$value)??'';$value=strip_tags($value,'<h2><h3><h4><p><ul><ol><li><strong><em><br>');return preg_replace_callback('#<(/?)(h2|h3|h4|p|ul|ol|li|strong|em|br)\b[^>]*>#i',fn($m)=>'<'.$m[1].strtolower($m[2]).'>',$value)??'';}
    private function selectOptions(array $options,string $selected): string{return implode('',array_map(fn($option)=>'<option'.($option===$selected?' selected':'').'>'.self::e($option).'</option>',$options));}
    private function logoutForm(): string{return'<form class="fd-inline" method="post" action="/admin/logout"><input type="hidden" name="csrf" value="'.self::e($this->csrf()).'"><button type="submit" class="fd-link-button">Sign out</button></form>';}
    private function authRateKey(string $identity): string{return hash('sha256','admin-login|'.$identity.'|'.($_SERVER['REMOTE_ADDR']??'').'|'.(getenv('APP_KEY')?:'local'));}
    private function loginBlocked(string $key): bool{$stmt=$this->db->prepare("SELECT blocked_until FROM auth_rate_limits WHERE rate_key=?");$stmt->execute([$key]);$blocked=$stmt->fetchColumn();return$blocked!==false&&$blocked!==null&&strtotime((string)$blocked)>time();}
    private function recordLoginAttempt(string $key,bool $success): void{if($success){$this->db->prepare("DELETE FROM auth_rate_limits WHERE rate_key=?")->execute([$key]);return;}$stmt=$this->db->prepare("INSERT INTO auth_rate_limits(rate_key,attempts,window_started_at,blocked_until) VALUES(?,1,NOW(),NULL) ON DUPLICATE KEY UPDATE attempts=IF(window_started_at<DATE_SUB(NOW(),INTERVAL 15 MINUTE),1,attempts+1),window_started_at=IF(window_started_at<DATE_SUB(NOW(),INTERVAL 15 MINUTE),NOW(),window_started_at),blocked_until=IF(IF(window_started_at<DATE_SUB(NOW(),INTERVAL 15 MINUTE),1,attempts+1)>=5,DATE_ADD(NOW(),INTERVAL 15 MINUTE),NULL)");$stmt->execute([$key]);}
    private function enforcePublicRateLimit(string $scope,int $limit,int $seconds): void{$key=hash('sha256',$scope.'|'.($_SERVER['REMOTE_ADDR']??'').'|'.(getenv('APP_KEY')?:'local'));$seconds=max(1,min(86400,$seconds));$stmt=$this->db->prepare("SELECT COUNT(*) FROM auth_attempts WHERE identity_hash=? AND attempted_at>=DATE_SUB(NOW(),INTERVAL $seconds SECOND)");$stmt->execute([$key]);if((int)$stmt->fetchColumn()>=$limit)throw new RateLimitException('Too many requests. Please try again later.',$seconds);$this->db->prepare("INSERT INTO auth_attempts(identity_hash,attempted_at,success) VALUES(?,NOW(),1)")->execute([$key]);}
    private function methodNotAllowed(array $allow): never{$this->json(['error'=>['message'=>'Method not allowed.','status'=>405]],405,['Allow'=>implode(', ',$allow)]);}
    private function allowedMethods(string $path): string{return match($path){'/api/health','/api/categories','/api/products','/api/product','/api/recaptcha-public','/api/tracking-config','/api/brochure','/api/brochure.php'=>'GET','/api/quotes'=>'GET, POST',default=>'POST'};}
    private function notFound(): void{$this->layout('Page not found','<section class="fd-page"><h1>Page not found</h1><p>The page or product is unavailable.</p><a class="fd-btn" href="/shop">Return to shop</a></section>',404,'The requested page was not found.');}
    private static function safeFilename(string $value): string{return preg_replace('/[^A-Za-z0-9._-]+/','-',basename($value))?:'brochure.pdf';}
    private static function safeExternalUrl(string $value): string{$scheme=strtolower((string)parse_url($value,PHP_URL_SCHEME));return filter_var($value,FILTER_VALIDATE_URL)&&in_array($scheme,['http','https'],true)?$value:'';}
    private static function e(string $value): string{return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private static function money(mixed $value): string{return$value===null?'Price pending':'R'.number_format((float)$value,0,'.',' ');}
}
